(()=>{const $=id=>document.getElementById(id);let token=sessionStorage.getItem('portfolio_admin_token')||'',type='experiences',items=[];const api=async(path,opts={})=>{const r=await fetch('/api/'+path,{...opts,headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{}),...(opts.headers||{})}});let data={};try{data=await r.json()}catch{}if(!r.ok)throw Error(data.error||'Request failed ('+r.status+')');return data};function msg(id,text){$(id).textContent=text}function reset(){['itemId','title','subtitle','date','description','bullets','image','tags'].forEach(x=>$(x).value='');$('formTitle').textContent='Add item'}function fill(x){$('itemId').value=x.id||'';$('title').value=x.title||'';$('subtitle').value=x.subtitle||'';$('date').value=x.date||'';$('description').value=x.description||'';$('bullets').value=(x.bullets||[]).join('\n');$('image').value=x.image||'';$('tags').value=(x.tags||[]).join(', ');$('formTitle').textContent='Edit item'}function escape(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function render(){ $('itemsList').innerHTML=items.length?items.map(x=>`<article class="admin-item"><strong>${escape(x.title)}</strong><p>${escape(x.subtitle)} ${escape(x.date)}</p>${x.image?`<p class="admin-note">Image: ${escape(x.image)}</p>`:''}<div class="admin-actions"><button data-edit="${escape(x.id)}">Edit</button><button data-delete="${escape(x.id)}">Delete</button></div></article>`).join(''):'<p>No saved items yet. Existing static content remains visible until you add content.'; $('itemsList').querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const x=items.find(x=>x.id===b.dataset.edit);if(x)fill(x)});$('itemsList').querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this item?'))return;try{await api('admin/items/'+encodeURIComponent(b.dataset.delete),{method:'DELETE'});await load();reset()}catch(e){alert(e.message)}})}async function load(){const d=await api('admin/items?type='+type);items=d.items||[];render()}function show(){ $('loginPanel').classList.add('admin-hidden');$('workspace').classList.remove('admin-hidden');load().catch(e=>{msg('saveMsg',e.message);if(e.message.includes('Unauthorized'))logout()})}function logout(){token='';sessionStorage.removeItem('portfolio_admin_token');$('workspace').classList.add('admin-hidden');$('loginPanel').classList.remove('admin-hidden')} $('loginForm').addEventListener('submit',async e=>{e.preventDefault();msg('loginMsg','Signing in…');try{const d=await api('admin/login',{method:'POST',body:JSON.stringify({password:$('password').value})});token=d.token;sessionStorage.setItem('portfolio_admin_token',token);$('password').value='';msg('loginMsg','');show()}catch(e){msg('loginMsg',e.message)}});document.querySelectorAll('[data-type]').forEach(b=>b.addEventListener('click',()=>{type=b.dataset.type;reset();load().catch(e=>msg('saveMsg',e.message))}));$('itemForm').addEventListener('submit',async e=>{e.preventDefault();const item={type,title:$('title').value.trim(),subtitle:$('subtitle').value.trim(),date:$('date').value.trim(),description:$('description').value.trim(),bullets:$('bullets').value.split('\n').map(x=>x.trim()).filter(Boolean),image:$('image').value.trim(),tags:$('tags').value.split(',').map(x=>x.trim()).filter(Boolean)};try{const id=$('itemId').value;await api('admin/items'+(id?'/'+encodeURIComponent(id):''),{method:id?'PUT':'POST',body:JSON.stringify(item)});msg('saveMsg','Saved successfully.');reset();await load()}catch(e){msg('saveMsg',e.message)}});$('newBtn').onclick=reset;$('logoutBtn').onclick=logout;if(token)show()})();